import React, { useState } from 'react'
import {
  ResponsiveContainer,
  PieChart, Pie, Cell,
  BarChart, Bar, XAxis, YAxis, Tooltip
} from 'recharts'
import { loadScanData } from '../api/scan'

const RISK_COLORS = {
  safe:    '#60a5fa',
  warning: '#facc15',
  danger:  '#ef4444',
}
const VULN_COLORS = {
  low:    '#10b981',
  medium: '#f59e0b',
  high:   '#ef4444',
}

export default function ScanPage() {
  const [target, setTarget]     = useState('')
  const [scanData, setScanData] = useState(null)
  const [loading, setLoading]   = useState(false)
  const [error, setError]       = useState('')

  const onSubmit = async e => {
    e.preventDefault()
    if (!target.trim()) {
      setError('IP 또는 도메인을 입력하세요')
      return
    }
    setError(''); setLoading(true)
    try {
      const data = await loadScanData(target)
      setScanData(data)
    } catch (e) {
      setError(e.message)
    } finally {
      setLoading(false)
    }
  }

  // PieData 준비
  const vulnPieData = scanData
    ? ['low','medium','high'].map(k => ({
        name: k,
        value: scanData.vulnerabilities.filter(v=>v.severity===k).length
      })).filter(x=>x.value>0)
    : []
  const riskPieData = scanData
    ? ['safe','warning','danger'].map(k => ({
        name: k,
        value: scanData.risks.filter(r=>r.level===k).length
      })).filter(x=>x.value>0)
    : []

  return (
    <main className="max-w-5xl mx-auto p-6 font-sans space-y-8">

      {/* 결과 요약 카드 */}
      {scanData && (
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div className="bg-white shadow rounded p-4">
            <p className="text-sm text-gray-500 mb-1">스캔 대상</p>
            <p className="text-lg text-gray-800">
              {scanData.target} ({scanData.ip})
            </p>
          </div>
          <div className="bg-white shadow rounded p-4">
            <p className="text-sm text-gray-500 mb-1">열린 포트 개수</p>
            <p className="text-3xl font-semibold">{scanData.ports.length}</p>
          </div>
          <div className="bg-white shadow rounded p-4">
            <p className="text-sm text-gray-500 mb-1">자산 개수</p>
            <p className="text-3xl font-semibold">{scanData.assets.length}</p>
          </div>
        </div>
      )}

      {/* 차트 영역 */}
      {scanData && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {/* 1) Assets Bar */}
          <div className="bg-white shadow rounded p-4 flex flex-col">
            <h3 className="text-lg mb-2">Assets 개수</h3>
            <ResponsiveContainer width="100%" height={160}>
              <BarChart
                data={[{ name: 'Assets', value: scanData.assets.length }]}
              >
                <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                <YAxis allowDecimals={false} tick={{ fontSize: 12 }} />
                <Tooltip />
                <Bar dataKey="value" fill="#2563EB" />
              </BarChart>
            </ResponsiveContainer>
          </div>

          {/* 2) Vulnerabilities Pie */}
          <div className="bg-white shadow rounded p-4 flex flex-col">
            <h3 className="text-lg mb-2">취약점 심각도</h3>
            <ResponsiveContainer width="100%" height={160}>
              <PieChart>
                <Pie
                  data={vulnPieData}
                  dataKey="value"
                  nameKey="name"
                  outerRadius={60}
                  label
                >
                  {vulnPieData.map((e,i)=>(
                    <Cell key={i} fill={VULN_COLORS[e.name]} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>

          {/* 3) Risks Pie */}
          <div className="bg-white shadow rounded p-4 flex flex-col">
            <h3 className="text-lg mb-2">위험도 분포</h3>
            <ResponsiveContainer width="100%" height={160}>
              <PieChart>
                <Pie
                  data={riskPieData}
                  dataKey="value"
                  nameKey="name"
                  outerRadius={60}
                  label
                >
                  {riskPieData.map((e,i)=>(
                    <Cell key={i} fill={RISK_COLORS[e.name]} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {/* 포트 테이블 */}
      {scanData && (
        <div className="bg-white shadow rounded p-4 overflow-x-auto">
          <h3 className="text-lg mb-2">포트 스캔 결과</h3>
          <table className="min-w-full text-sm text-left border-collapse">
            <thead>
              <tr className="bg-gray-100">
                {['Port','Service','Version'].map(h => (
                  <th
                    key={h}
                    className="border px-3 py-1 text-gray-600 font-medium"
                  >
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {scanData.ports.map((p, i) => (
                <tr key={i} className="odd:bg-gray-50">
                  <td className="border px-3 py-1">{p.port}</td>
                  <td className="border px-3 py-1">{p.service}</td>
                  <td className="border px-3 py-1">{p.version}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </main>
  )
}
